package com.nexusdrive.metadata.entity;import com.nexusdrive.common.enums.ShareVisibility;import jakarta.persistence.*;import java.util.UUID;@Entity@Table(name="share_permissions")public class SharePermission{@Id private UUID id;@ManyToOne(optional=false,fetch=FetchType.LAZY)@JoinColumn(name="file_id")private FileMetadata file;@Column(name="shared_with_user_id")private UUID sharedWithUserId;@Enumerated(EnumType.STRING)@Column(nullable=false)private ShareVisibility visibility;@Enumerated(EnumType.STRING)@Column(nullable=false)private Permission permission;public enum Permission{READ,WRITE}@PrePersist void pre(){if(id==null)id=UUID.randomUUID();}}
